-- Reviewed movements between processor funds and disputed-funds receivable.
-- Fees are explicitly recorded gross with NO tax claim. This is not a loss
-- write-off,tuition refund,provider operation or dispute-attention release.
-- Match ECMAScript trim for pasted provider IDs,including tabs,newlines and
-- nonbreaking spaces. Historical reference text itself is never rewritten.
CREATE FUNCTION public.provider_transaction_reference(p_text text) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$ SELECT btrim(p_text,U&'\0009\000a\000b\000c\000d\0020\00a0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200a\2028\2029\202f\205f\3000\feff') $$;
REVOKE ALL ON FUNCTION public.provider_transaction_reference(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_transaction_reference(text) TO kavosh_runtime;
CREATE INDEX finance_journal_provider_reference ON public.finance_journals(academy_id,public.provider_transaction_reference(reference));
CREATE TABLE public.provider_dispute_postings(
 academy_id uuid NOT NULL,id uuid NOT NULL,collection_id uuid NOT NULL,balance_inspection_id uuid NOT NULL,account_id text NOT NULL,livemode boolean NOT NULL,transaction_id text NOT NULL,dispute_id text NOT NULL,
 processor_account uuid NOT NULL,disputed_account uuid NOT NULL,fee_account uuid,gross_minor numeric NOT NULL,fee_minor numeric NOT NULL,net_minor numeric NOT NULL,posted_on date NOT NULL,source jsonb NOT NULL,approval_id uuid NOT NULL,created_by uuid NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,account_id,livemode,transaction_id),
 FOREIGN KEY(academy_id,collection_id) REFERENCES public.provider_collections(academy_id,id),FOREIGN KEY(academy_id,balance_inspection_id) REFERENCES public.checkout_dispute_balance_inspections(academy_id,id),
 FOREIGN KEY(academy_id,processor_account) REFERENCES public.finance_accounts(academy_id,id),FOREIGN KEY(academy_id,disputed_account) REFERENCES public.finance_accounts(academy_id,id),FOREIGN KEY(academy_id,fee_account) REFERENCES public.finance_accounts(academy_id,id),
 FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX provider_dispute_collection ON public.provider_dispute_postings(academy_id,collection_id,posted_on,id);
CREATE INDEX checkout_dispute_balance_transaction ON public.checkout_dispute_balance_inspections(academy_id,(balance_inspection->>'balanceTransactionId'),received_at,id);
ALTER TABLE public.provider_dispute_postings ENABLE ROW LEVEL SECURITY;ALTER TABLE public.provider_dispute_postings FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_boundary ON public.provider_dispute_postings USING(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid) WITH CHECK(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid);
CREATE TRIGGER finance_book_write BEFORE INSERT OR UPDATE OR DELETE ON public.provider_dispute_postings FOR EACH STATEMENT EXECUTE FUNCTION public.guard_finance_book_write();
GRANT SELECT,INSERT ON public.provider_dispute_postings TO kavosh_runtime;
CREATE FUNCTION public.provider_dispute_source(p_collection uuid,p_balance uuid,p_on date,p_processor uuid,p_disputed uuid,p_fee uuid,p_exclude uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$
DECLARE c record;e record;h record;d record;f record;collector record;latest record;current_dispute jsonb;history jsonb;s jsonb;j jsonb;lines jsonb:='[]'::jsonb;gross numeric;fee numeric;net numeric;factor numeric;booked uuid;BEGIN
 SELECT pc.*,q.currency_code original_currency,cl.time_zone INTO c FROM public.provider_collections pc JOIN public.payment_checkout_dispatch_starts st ON st.academy_id=pc.academy_id AND st.id=pc.start_id JOIN public.payment_checkout_attempts a ON a.academy_id=st.academy_id AND a.id=st.attempt_id JOIN public.payment_checkout_requests q ON q.academy_id=a.academy_id AND q.id=a.request_id JOIN public.classes cl ON cl.academy_id=pc.academy_id AND cl.id=pc.class_id WHERE pc.id=p_collection;
 SELECT * INTO e FROM public.checkout_dispute_balance_inspections WHERE academy_id=c.academy_id AND id=p_balance AND start_id=c.start_id;
 IF c.id IS NULL OR e.id IS NULL OR e.object_conflict OR e.balance_inspection->>'chargeId' IS DISTINCT FROM c.charge_id OR e.balance_inspection->'recognizedDisputeAdjustment' IS DISTINCT FROM 'true'::jsonb OR e.balance_inspection->>'sourceBinding' IS DISTINCT FROM 'dispute' OR e.balance_inspection->>'balanceType' IS DISTINCT FROM 'payments'
 OR p_on IS NULL OR p_on NOT BETWEEN DATE '0001-01-01' AND DATE '9999-12-31' OR p_on<c.received_on OR p_on<(to_timestamp((e.balance_inspection->>'createdAt')::double precision) AT TIME ZONE c.time_zone)::date THEN RETURN NULL;END IF;
 j=e.balance_inspection;
 SELECT * INTO latest FROM public.checkout_dispute_balance_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id AND balance_inspection->>'balanceTransactionId'=j->>'balanceTransactionId' ORDER BY received_at DESC,id DESC LIMIT 1;
 IF latest.object_conflict OR latest.balance_inspection-ARRAY['status','availableOn'] IS DISTINCT FROM j-ARRAY['status','availableOn']
 OR EXISTS(SELECT 1 FROM public.checkout_dispute_balance_inspections bad JOIN public.payment_checkout_dispatch_starts st ON st.academy_id=bad.academy_id AND st.id=bad.start_id JOIN public.payment_checkout_attempts a ON a.academy_id=st.academy_id AND a.id=st.attempt_id WHERE bad.academy_id=c.academy_id AND a.draft->>'accountId'=c.account_id AND(a.draft->>'livemode')::boolean=c.livemode AND bad.object_conflict AND bad.balance_inspection->>'balanceTransactionId'=j->>'balanceTransactionId')
 OR NOT EXISTS(SELECT 1 FROM public.checkout_dispute_balance_bindings b WHERE b.academy_id=c.academy_id AND b.account_id=c.account_id AND b.livemode=c.livemode AND b.transaction_id=j->>'balanceTransactionId' AND b.start_id=c.start_id AND b.dispute_id=e.dispute_id AND b.amount=(j->>'grossAmount')::numeric AND b.currency=j->>'currency')
 OR NOT EXISTS(SELECT 1 FROM public.checkout_balance_object_bindings b WHERE b.academy_id=c.academy_id AND b.account_id=c.account_id AND b.livemode=c.livemode AND b.transaction_id=j->>'balanceTransactionId' AND b.start_id=c.start_id AND b.charge_id=c.charge_id) THEN RETURN NULL;END IF;
 SELECT v.value INTO current_dispute FROM public.checkout_dispute_inspections i CROSS JOIN LATERAL jsonb_array_elements(i.dispute_inspection->'disputes') v WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id AND v.value->>'id'=e.dispute_id ORDER BY i.received_at DESC,i.id DESC LIMIT 1;
 IF current_dispute IS NULL OR current_dispute->'amount' IS DISTINCT FROM j->'disputeAmount' OR current_dispute->'currency' IS DISTINCT FROM j->'disputeCurrency' OR current_dispute->'createdAt' IS DISTINCT FROM j->'disputeCreatedAt' OR NOT(current_dispute->'balanceTransactionIds' ? (j->>'balanceTransactionId'))
 OR EXISTS(SELECT 1 FROM public.checkout_dispute_inspections bad WHERE bad.academy_id=c.academy_id AND bad.start_id=c.start_id AND bad.object_conflict AND bad.dispute_inspection->'disputes' @> jsonb_build_array(jsonb_build_object('id',e.dispute_id))) THEN RETURN NULL;END IF;
 SELECT * INTO h FROM public.finance_account_catalogue WHERE academy_id=c.academy_id AND id=p_processor;SELECT * INTO d FROM public.finance_account_catalogue WHERE academy_id=c.academy_id AND id=p_disputed;SELECT * INTO f FROM public.finance_account_catalogue WHERE academy_id=c.academy_id AND id=p_fee;
 SELECT x.id,x.version,x.custody,r.active,r.accounts INTO collector FROM public.finance_collectors x JOIN public.finance_collector_revisions r ON r.academy_id=x.academy_id AND r.collector_id=x.id AND r.version=x.version WHERE x.academy_id=c.academy_id AND x.id=c.collector_id;
 IF h.id IS NULL OR d.id IS NULL OR h.id=d.id OR h.id=p_fee OR d.id=p_fee OR NOT h.active OR NOT d.active OR h.kind<>'asset' OR h.normal_balance<>'debit' OR h.operational_role<>'collector_receivable' OR d.kind<>'asset' OR d.normal_balance<>'debit' OR d.operational_role<>'other'
 OR h.currency_code IS DISTINCT FROM upper(j->>'currency') OR d.currency_id<>h.currency_id OR d.unit_scale<>h.unit_scale OR(h.hub_id IS NOT NULL AND h.hub_id<>c.hub_id) OR(d.hub_id IS NOT NULL AND d.hub_id<>c.hub_id)
 OR collector.id IS NULL OR NOT collector.active OR collector.custody<>'third_party' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(collector.accounts) a WHERE a->>'id'=h.id::text AND a->>'currencyId'=h.currency_id::text)
 OR((j->>'feeAmount')::numeric<>0 AND(f.id IS NULL OR NOT f.active OR f.kind<>'expense' OR f.operational_role<>'expense' OR f.currency_id<>h.currency_id OR f.unit_scale<>h.unit_scale OR(f.hub_id IS NOT NULL AND f.hub_id<>c.hub_id))) OR((j->>'feeAmount')::numeric=0 AND p_fee IS NOT NULL) THEN RETURN NULL;END IF;
 factor=power(10::numeric,h.unit_scale)/power(10::numeric,(j->>'providerUnitScale')::integer);gross=(j->>'grossAmount')::numeric*factor;fee=(j->>'feeAmount')::numeric*factor;net=(j->>'netAmount')::numeric*factor;
 IF gross<>trunc(gross) OR fee<>trunc(fee) OR net<>trunc(net) OR greatest(abs(gross),abs(fee),abs(net))>=1e38 OR gross=0 OR net<>gross-fee THEN RETURN NULL;END IF;
 IF net<>0 THEN lines=lines||jsonb_build_array(jsonb_build_object('accountId',h.id,'accountVersion',h.version,'side',CASE WHEN net>0 THEN 'debit' ELSE 'credit' END,'amountMinor',trunc(abs(net))::text));END IF;
 lines=lines||jsonb_build_array(jsonb_build_object('accountId',d.id,'accountVersion',d.version,'side',CASE WHEN gross>0 THEN 'credit' ELSE 'debit' END,'amountMinor',trunc(abs(gross))::text));
 IF fee<>0 THEN lines=lines||jsonb_build_array(jsonb_build_object('accountId',f.id,'accountVersion',f.version,'side',CASE WHEN fee>0 THEN 'debit' ELSE 'credit' END,'amountMinor',trunc(abs(fee))::text));END IF;
 WITH facts AS(
 SELECT 'balance'::text stream,i.received_at,i.id,jsonb_build_object('conflict',i.object_conflict,'fact',i.balance_inspection-ARRAY['status','availableOn']) fact FROM public.checkout_dispute_balance_inspections i WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id AND i.balance_inspection->>'balanceTransactionId'=j->>'balanceTransactionId'
 UNION ALL SELECT 'dispute',i.received_at,i.id,jsonb_build_object('conflict',i.object_conflict,'fact',v.value) FROM public.checkout_dispute_inspections i CROSS JOIN LATERAL jsonb_array_elements(i.dispute_inspection->'disputes') v WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id AND v.value->>'id'=e.dispute_id
 ),transitions AS(SELECT *,lag(fact) OVER(PARTITION BY stream ORDER BY received_at,id) prior FROM facts)
 SELECT coalesce(jsonb_agg(jsonb_build_array(stream,fact) ORDER BY stream,received_at,id) FILTER(WHERE fact IS DISTINCT FROM prior),'[]'::jsonb) INTO history FROM transitions;
 SELECT id INTO booked FROM public.provider_dispute_postings WHERE academy_id=c.academy_id AND account_id=c.account_id AND livemode=c.livemode AND transaction_id=j->>'balanceTransactionId' AND(p_exclude IS NULL OR id<>p_exclude);
 s=jsonb_build_object('collectionId',c.id,'balanceInspectionId',e.id,'accountId',c.account_id,'livemode',c.livemode,'balanceTransactionId',j->>'balanceTransactionId','disputeId',e.dispute_id,'currentDisputeStatus',current_dispute->'status','invoiceId',c.invoice_id,'hubId',c.hub_id,'classId',c.class_id,'studentId',c.student_id,'collectorId',c.collector_id,'collectorVersion',collector.version,'processorAccountId',h.id,'processorVersion',h.version,'disputedAccountId',d.id,'disputedVersion',d.version,'feeAccountId',f.id,'feeVersion',f.version,'currencyId',h.currency_id,'currencyCode',h.currency_code,'unitScale',h.unit_scale,'originalCurrencyCode',c.original_currency,'requiresPrincipalReconciliation',h.id<>c.holding_account OR h.currency_code<>c.original_currency OR j->'disputeAmountMatched' IS DISTINCT FROM 'true'::jsonb,'grossMinor',trunc(gross)::text,'feeMinor',trunc(fee)::text,'netMinor',trunc(net)::text,'feeTaxTreatment',CASE WHEN fee=0 THEN 'no_fee' ELSE 'not_claimed' END,'lines',lines,'postedOn',p_on::text,'bookedId',booked,'manualReferenceExists',EXISTS(SELECT 1 FROM public.finance_journals m WHERE m.academy_id=c.academy_id AND public.provider_transaction_reference(m.reference)=j->>'balanceTransactionId' AND m.reverses_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.finance_journals v WHERE v.academy_id=m.academy_id AND v.reverses_id=m.id AND(v.posted_on<=p_on OR v.posted_on=m.posted_on))),'evidence',j,'evidenceNeedsReview',j->'requiresManualReview','historyStamp',encode(sha256(convert_to(history::text,'UTF8')),'hex'),'bankSettled',false,'taxEligibilityDetermined',false,'creditRestored',false);
 RETURN s;
END $$;
CREATE FUNCTION public.guard_provider_dispute_posting() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE c record;p record;s jsonb;BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_IMMUTABLE' USING ERRCODE='23514';END IF;
 SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=NEW.collection_id;PERFORM public.lock_customer_credit(c.id);
 PERFORM public.lock_collector_funds(c.collector_id,a.id) FROM(SELECT DISTINCT id FROM unnest(ARRAY[c.holding_account,NEW.processor_account]) id ORDER BY id) a;
 PERFORM id FROM public.tuition_invoices WHERE academy_id=NEW.academy_id AND id=c.invoice_id FOR UPDATE;PERFORM pg_advisory_xact_lock(hashtextextended(NEW.academy_id::text||':checkout-provider:'||c.account_id,0));
 IF NOT pg_try_advisory_xact_lock(hashtextextended(NEW.academy_id::text||':provider-dispute:'||NEW.transaction_id,0)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_REFERENCE_BUSY' USING ERRCODE='40001';END IF;
 s=public.provider_dispute_source(NEW.collection_id,NEW.balance_inspection_id,NEW.posted_on,NEW.processor_account,NEW.disputed_account,NEW.fee_account);SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 IF s IS NULL OR s->>'bookedId' IS NOT NULL OR s->'manualReferenceExists' IS DISTINCT FROM 'false'::jsonb OR NEW.source IS DISTINCT FROM s OR NEW.account_id IS DISTINCT FROM s->>'accountId' OR NEW.livemode IS DISTINCT FROM(s->>'livemode')::boolean OR NEW.transaction_id IS DISTINCT FROM s->>'balanceTransactionId' OR NEW.dispute_id IS DISTINCT FROM s->>'disputeId' OR NEW.gross_minor IS DISTINCT FROM(s->>'grossMinor')::numeric OR NEW.fee_minor IS DISTINCT FROM(s->>'feeMinor')::numeric OR NEW.net_minor IS DISTINCT FROM(s->>'netMinor')::numeric
 OR p.id IS NULL OR p.action IS DISTINCT FROM 'finance.provider-dispute.record' OR p.status IS DISTINCT FROM 'pending' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version<>0 OR p.privacy_capability IS DISTINCT FROM 'receipts.edit' OR p.review_context->'source' IS DISTINCT FROM s
 OR p.payload IS DISTINCT FROM jsonb_build_object('collectionId',NEW.collection_id,'balanceInspectionId',NEW.balance_inspection_id,'processorAccount',jsonb_build_object('id',NEW.processor_account,'version',(s->>'processorVersion')::integer),'disputedFundsAccount',jsonb_build_object('id',NEW.disputed_account,'version',(s->>'disputedVersion')::integer),'feeAccount',CASE WHEN NEW.fee_account IS NULL THEN 'null'::jsonb ELSE jsonb_build_object('id',NEW.fee_account,'version',(s->>'feeVersion')::integer) END,'feeTaxTreatment',s->'feeTaxTreatment','postedOn',NEW.posted_on::text,'period',p.payload->'period','reason',NEW.reason)
 OR p.scope->'recordContext' IS DISTINCT FROM jsonb_build_object('hubId',c.hub_id,'classId',c.class_id,'studentId',c.student_id) OR NOT public.report_comment_human_verified(NEW.created_by) OR NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND status='active') THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_SOURCE_OR_REVIEW_INVALID' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) AND(p.requester_id=NEW.created_by OR c.student_id=NEW.created_by OR EXISTS(SELECT 1 FROM public.family_relationships WHERE academy_id=NEW.academy_id AND student_id=c.student_id AND guardian_id=NEW.created_by) OR EXISTS(SELECT 1 FROM public.finance_collectors WHERE academy_id=NEW.academy_id AND id=c.collector_id AND person_id=NEW.created_by)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_UPPER_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER provider_dispute_posting BEFORE INSERT OR UPDATE OR DELETE ON public.provider_dispute_postings FOR EACH ROW EXECUTE FUNCTION public.guard_provider_dispute_posting();
CREATE FUNCTION public.complete_provider_dispute_posting() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;j record;actual jsonb;BEGIN
 IF NEW.source IS DISTINCT FROM public.provider_dispute_source(NEW.collection_id,NEW.balance_inspection_id,NEW.posted_on,NEW.processor_account,NEW.disputed_account,NEW.fee_account,NEW.id) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_COMPLETION_SOURCE_CHANGED' USING ERRCODE='23514';END IF;
 SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;SELECT * INTO j FROM public.finance_journals WHERE academy_id=NEW.academy_id AND id=NEW.id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('accountId',l.account_id,'accountVersion',l.account_version,'side',l.side,'amountMinor',trunc(l.amount_minor)::text) ORDER BY l.line_number),'[]'::jsonb) INTO actual FROM public.finance_journal_lines l WHERE l.academy_id=NEW.academy_id AND l.journal_id=NEW.id;
 IF p.status IS DISTINCT FROM 'applied' OR p.reviewer_id IS DISTINCT FROM NEW.created_by OR j.id IS NULL OR j.approval_id IS DISTINCT FROM NEW.approval_id OR j.posted_by IS DISTINCT FROM NEW.created_by OR j.posted_on IS DISTINCT FROM NEW.posted_on OR j.reverses_id IS NOT NULL OR j.purpose IS DISTINCT FROM 'activity' OR j.reference IS DISTINCT FROM 'provider-dispute:'||NEW.id::text OR j.period_id IS DISTINCT FROM(p.payload#>>'{period,id}')::uuid OR j.period_version IS DISTINCT FROM(p.payload#>>'{period,version}')::integer OR j.line_count<>jsonb_array_length(NEW.source->'lines') OR actual IS DISTINCT FROM NEW.source->'lines'
 OR NOT EXISTS(SELECT 1 FROM public.audit_events WHERE academy_id=NEW.academy_id AND entity_id=NEW.id AND actor_id=NEW.created_by AND created_at=transaction_timestamp() AND action='finance.provider-dispute.recorded' AND changes=jsonb_build_object('approvalId',NEW.approval_id,'collectionId',NEW.collection_id,'severity','critical','providerOperationPerformed',false,'bankSettled',false,'creditRestored',false)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_POSTING_INCOMPLETE' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER provider_dispute_complete AFTER INSERT ON public.provider_dispute_postings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.complete_provider_dispute_posting();
CREATE FUNCTION public.provider_dispute_effect_required() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.status='applied' AND NEW.action='finance.provider-dispute.record' AND NOT EXISTS(SELECT 1 FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER provider_dispute_effect AFTER INSERT OR UPDATE ON public.approval_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.provider_dispute_effect_required();
CREATE FUNCTION public.provider_dispute_journal_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE canonical text:=public.provider_transaction_reference(NEW.reference);BEGIN
 IF NEW.reverses_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND id=NEW.reverses_id) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_CORRECTION_WORKFLOW_REQUIRED' USING ERRCODE='23514';END IF;
 IF canonical LIKE 'provider-dispute:%' AND NOT EXISTS(SELECT 1 FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND id=NEW.id AND approval_id=NEW.approval_id) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;
 IF canonical~'^txn_[A-Za-z0-9]+$' THEN IF NOT pg_try_advisory_xact_lock(hashtextextended(NEW.academy_id::text||':provider-dispute:'||canonical,0)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_REFERENCE_BUSY' USING ERRCODE='40001';END IF;IF EXISTS(SELECT 1 FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND transaction_id=canonical) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_ALREADY_RECORDED' USING ERRCODE='23514';END IF;END IF;RETURN NEW;
END $$;
CREATE TRIGGER provider_dispute_journal BEFORE INSERT ON public.finance_journals FOR EACH ROW EXECUTE FUNCTION public.provider_dispute_journal_guard();
-- Reuse original invoice/collector privacy,then bind every selected account.
CREATE FUNCTION public.provider_dispute_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE c record;hubs uuid[];ch uuid;BEGIN
 SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=(NEW.payload->>'collectionId')::uuid;
 IF c.id IS NULL THEN NEW.privacy_bindings=NEW.privacy_bindings||'[{"unresolved":true}]'::jsonb;RETURN NEW;END IF;
 NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','receipts.view','scope',NEW.scope),jsonb_build_object('capability','checkouts.view','scope',NEW.scope),jsonb_build_object('capability','invoices.view','scope',NEW.scope));
 IF NEW.payload->'feeAccount'<>'null'::jsonb THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','expenses.view','scope',NEW.scope));END IF;
 SELECT array_agg(hub_id ORDER BY id) INTO hubs FROM public.finance_accounts WHERE academy_id=NEW.academy_id AND id IN(c.credit_account,c.holding_account,(NEW.payload#>>'{processorAccount,id}')::uuid,(NEW.payload#>>'{disputedFundsAccount,id}')::uuid,(NEW.payload#>>'{feeAccount,id}')::uuid);SELECT hub_id INTO ch FROM public.finance_collectors WHERE academy_id=NEW.academy_id AND id=c.collector_id;
 NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(public.approval_hub_binding('accounts.view',hubs),public.approval_hub_binding('journals.view',hubs),public.approval_hub_binding('collectors.view',ARRAY[ch]));RETURN NEW;
END $$;
CREATE TRIGGER zz_provider_dispute_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action='finance.provider-dispute.record') EXECUTE FUNCTION public.provider_dispute_privacy();
DO $$ DECLARE definition text;BEGIN definition=pg_get_viewdef('public.collector_fund_events'::regclass,true);EXECUTE 'CREATE OR REPLACE VIEW public.collector_fund_events WITH(security_invoker=true) AS '||rtrim(definition,E';\n ')||' UNION ALL SELECT p.academy_id,c.collector_id,p.processor_account,p.id,p.posted_on,p.net_minor FROM public.provider_dispute_postings p JOIN public.provider_collections c ON c.academy_id=p.academy_id AND c.id=p.collection_id';END $$;
REVOKE ALL ON FUNCTION public.provider_dispute_source(uuid,uuid,date,uuid,uuid,uuid,uuid),public.guard_provider_dispute_posting(),public.complete_provider_dispute_posting(),public.provider_dispute_effect_required(),public.provider_dispute_journal_guard(),public.provider_dispute_privacy() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_dispute_source(uuid,uuid,date,uuid,uuid,uuid,uuid) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 330 $$;
